def sum(a, b):
    return a + b

print(sum(2, 3))

def multiply(a, b):
    return a * b

print(multiply(2, 3), multiply(0, 5), multiply(-1, 4))

def divide(a, b):
    if b == 0:
        return None
    return a // b

if divide(10, 2) == 5 and divide(10, 0) is None:
    print('ok')

def validate(age):
    if age < 0:
        raise ValueError('age cannot be negative')

try:
    validate(-5)
except ValueError as e:
    print('yes' if 'negative' in str(e) else 'no')

def sum(a, b):
    return a + b

for _ in range(10000):
    sum(2, 3)
print('done', end='')
